import{_ as i}from"./index-JuibdC0a.js";import{az as l}from"./@vue-De9RwyRn.js";import"./element-plus-CKJIAC2w.js";import"./lodash-es-Ceiv_TW4.js";import"./@vueuse-Ihwzeb_o.js";import"./@element-plus-B-y2LHuz.js";import"./async-validator-j0i5Y79Y.js";import"./@popperjs-DxtSUbXb.js";import"./@ctrl-DGnlsNIE.js";import"./dayjs-KsS9adaU.js";import"./memoize-one-BAtLgO95.js";import"./normalize-wheel-es-TzhA1irr.js";import"./@floating-ui-BQjuueHq.js";import"./pinia-Dndd2XNl.js";import"./crypto-js-B6L3KfD1.js";import"./vue-i18n-DB7lm_w-.js";import"./@intlify-D8hALvN4.js";import"./vue-router-DNsliMEH.js";import"./pinia-plugin-persistedstate-COWkwNh5.js";const s=i({},[["render",function(i,s){return s[0]||(s[0]=l('<div class="helpBoxTop">一、基本配置</div><div class="helpDesTxt"> 网络录像机的系统信息包括设备型号、序列号、版本信息、通道个数、硬盘个数、报警输入输出数。在该界面，您可以设置网络录像机“设备名称”、及 “设备编号”。 </div><div class="helpBoxTop">二、时间设置</div><ul><li>在“时间设置”界面，您可以设置网络录像机时区及进行校时。</li><li> 设置时区：进入时间设置配置界面，可以对网络录像机进行校时。“时区”显示当前设备所在的时区并可根据实际情况进行设置。 </li><li> NTP校时：您可设置NTP服务器地址、NTP端口号和校时时间间隔，设备即按照设置每隔一段时间校时一次。 </li><li> 手动校时：勾选“手动校时”并手动输入设备时间，当勾选“与计算机时间同步”即可保持网络录像机与本地计算机时间一致。 </li></ul><div class="helpBoxTop">三、系统维护</div><div class="helpBoxTopChild">升级维护</div><ul><li>重启设备：单击“重启”，重新启动录像机。</li><li> 恢复默认值 <ul style="list-style-type:circle;"><li> 简单恢复：简单恢复设备参数，指除IP地址、子网掩码、网关、用户信息和制式等信息外的其它参数均恢复到出厂设置。 </li><li>完全恢复：完全恢复设备参数到出厂设置。</li></ul></li><li>参数导入与导出：参数文件导入和导出功能可方便用户进行网络录像机设置相同参数。</li><li> 升级 <ul style="list-style-type:circle;"><li> 升级文件：当网络录像机需要升级时，您可将升级程序拷贝到本地计算机，单击“浏览”选择升级文件存放的路径，单击“升级”开始升级。 </li></ul></li><li>设备自动维护：勾选“启用定时重启”，并设置维护时间，设备将在设置的时间进行重启维护。</li></ul><div class="helpDesTxt"><span class="helpTip">注意：</span><span class="helpBold">升级成功后网络录像机自动重新启动，请不要关闭电源。</span></div><div class="helpBoxTopChild">日志</div><div class="helpDesTxt">1、日志查询</div><div class="helpDesText">1） 设置需要日志查询的类型和时间段。</div><div class="helpDesText">2） 单击“查找”，查询完成后显示相应日志信息。</div><div class="helpDesText">说明</div><div class="helpDesText">若搜索到的日志超过2000条，系统将显示前2000条，每页显示100条。</div><div class="helpDesTxt">2、日志保存</div><div class="helpDesText">1） 单击“保存日志”，弹出存储路径界面。</div><div class="helpDesText">2） 选择保存路径，输入“文件名”和“保存类型”。</div><div class="helpDesText">3） 单击“保存”，完成日志文件保存。</div><div class="helpBoxTop" style="margin-top:8px;">四、安全管理</div><ul><li> 认证方式：通过设置RTSP认证和Web认证，可以有效保护实时视图的数据流。系统默认开启RTSP服务。若开启该服务，选择RTSP认证方式：digest、digest/basic。当选择digest认证方式时，仅带有digest身份验证请求的IP地址能通过RTSP协议访问实时视图的数据流。出于安全考虑，建议选择digest作为RTSP认证方式。 </li><li> 安全服务：若勾选“启用SSH”，则可以通过SSH登录设备。出于安全考虑，建议启用码流加密和图片URL摘要认证，非必要时不建议启用SSH。 </li></ul><div class="helpBoxTop">五、用户管理</div><div class="helpDesText" style="margin-top:8px;"> 网络录像机有缺省的用户名和密码，为了保证网络录像机的安全性，请登录后及时修改网络录像机的缺省用户名对应的密码。当使用缺省用户名登录系统时，您可以按实际需要创建其它用户，最多可以创建31个用户。 </div><ul><li>单击“添加”可添加新用户，您可以设置用户的类型、密码及其权限。</li><li>单击“修改”可修改已经添加的用户信息。</li><li>单击“删除”可删除作废的用户信息。</li><li>单击“本地锁屏时预览设置”可选择本地锁屏时可预览的通道。</li></ul>',23))}]]);export{s as default};
